struct EmailNotification {
    std::string recipient;
    std::string subject;
    std::string body;
    std::vector<std::pair<std::string, std::string>> headers;
};

class ContentEncoder {
public:
    static std::string encode_header_value(const std::string& value) {
        std::string encoded;
        encoded.reserve(value.size());
        for (unsigned char c : value) {
            if (c >= 0x20 && c <= 0x7E && c != '"' && c != '\\') {
                encoded += static_cast<char>(c);
            } else {
                char buf[5];
                snprintf(buf, sizeof(buf), "=%02X", c);
                encoded += buf;
            }
        }
        return encoded;
    }

    static std::string normalize_line_endings(const std::string& input) {
        std::string result;
        result.reserve(input.size());
        for (size_t i = 0; i < input.size(); ++i) {
            if (input[i] == '\r' && i + 1 < input.size() && input[i + 1] == '\n') {
                result += '\n';
                ++i;
            } else {
                result += input[i];
            }
        }
        return result;
    }
};

class EncryptedStorage {
    std::vector<unsigned char> key_;

public:
    EncryptedStorage() : key_(32) {
        RAND_bytes(key_.data(), 32);
    }

    std::vector<unsigned char> encrypt(const std::string& plaintext) {
        std::vector<unsigned char> iv(12);
        RAND_bytes(iv.data(), 12);

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, key_.data(), iv.data());

        std::vector<unsigned char> ciphertext(plaintext.size() + 16 + 12);
        std::copy(iv.begin(), iv.end(), ciphertext.begin());

        int len = 0;
        EVP_EncryptUpdate(ctx, ciphertext.data() + 12, &len,
            reinterpret_cast<const unsigned char*>(plaintext.data()), plaintext.size());
        int total = len;
        EVP_EncryptFinal_ex(ctx, ciphertext.data() + 12 + total, &len);
        total += len;

        unsigned char tag[16];
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
        std::copy(tag, tag + 16, ciphertext.data() + 12 + total);

        ciphertext.resize(12 + total + 16);
        EVP_CIPHER_CTX_free(ctx);
        return ciphertext;
    }

    std::string decrypt(const std::vector<unsigned char>& ciphertext) {
        if (ciphertext.size() < 28) return "";

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, key_.data(), ciphertext.data());

        int ct_len = ciphertext.size() - 12 - 16;
        std::vector<unsigned char> plaintext(ct_len);
        int len = 0;
        EVP_DecryptUpdate(ctx, plaintext.data(), &len, ciphertext.data() + 12, ct_len);

        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_TAG, 16,
            const_cast<unsigned char*>(ciphertext.data() + 12 + ct_len));

        int ret = EVP_DecryptFinal_ex(ctx, plaintext.data() + len, &len);
        EVP_CIPHER_CTX_free(ctx);

        if (ret <= 0) return "";
        return std::string(plaintext.begin(), plaintext.end());
    }
};

class FileProcessingService {
    EncryptedStorage storage_;

    struct FileMetadata {
        std::string filename;
        std::string uploader_email;
        std::string description;
        size_t size;
    };

    FileMetadata parse_metadata(const std::string& decrypted_meta) {
        FileMetadata meta{};
        std::istringstream stream(decrypted_meta);
        std::string line;
        while (std::getline(stream, line)) {
            auto pos = line.find(':');
            if (pos == std::string::npos) continue;
            std::string key = line.substr(0, pos);
            std::string val = line.substr(pos + 1);
            // Trim leading space
            if (!val.empty() && val[0] == ' ') val = val.substr(1);

            if (key == "filename") meta.filename = val;
            else if (key == "uploader") meta.uploader_email = val;
            else if (key == "description") meta.description = val;
            else if (key == "size") meta.size = std::stoull(val);
        }
        return meta;
    }

    std::string build_subject(const FileMetadata& meta) {
        // Subject includes filename for user convenience
        return "File processed: " + meta.filename;
    }

    std::string sanitize_email_address(const std::string& email) {
        std::string clean;
        for (char c : email) {
            if (c == '\r' || c == '\n') continue;
            clean += c;
        }
        return clean;
    }

    EmailNotification compose_notification(const FileMetadata& meta) {
        EmailNotification notif;
        notif.recipient = sanitize_email_address(meta.uploader_email);
        notif.subject = build_subject(meta);
        notif.body = "Your file '" + meta.filename + "' (" + 
                     std::to_string(meta.size) + " bytes) has been processed.\n" +
                     "Description: " + meta.description;

        notif.headers.push_back({"X-Service", "FileProcessor/1.0"});
        notif.headers.push_back({"X-File-Size", std::to_string(meta.size)});
        return notif;
    }

public:
    std::string format_email(const EmailNotification& notif) {
        std::ostringstream email;
        email << "To: " << notif.recipient << "\r\n";
        email << "Subject: " << notif.subject << "\r\n";
        for (const auto& [key, value] : notif.headers) {
            email << key << ": " << ContentEncoder::encode_header_value(value) << "\r\n";
        }
        email << "MIME-Version: 1.0\r\n";
        email << "Content-Type: text/plain; charset=UTF-8\r\n";
        email << "\r\n";
        email << notif.body;
        return email.str();
    }

    std::string process_file(const std::vector<unsigned char>& encrypted_metadata,
                            const std::vector<unsigned char>& encrypted_content) {
        std::string meta_str = storage_.decrypt(encrypted_metadata);
        if (meta_str.empty()) return "ERROR: decryption failed";

        // Normalize line endings from decrypted metadata
        meta_str = ContentEncoder::normalize_line_endings(meta_str);

        FileMetadata meta = parse_metadata(meta_str);

        // Store processed content
        std::string content = storage_.decrypt(encrypted_content);
        auto stored = storage_.encrypt(content);

        // Compose and return notification email
        EmailNotification notif = compose_notification(meta);
        return format_email(notif);
    }
};

